from pathlib import Path

FILES = {'requirements.txt': 'aiogram>=3.4.1\nplaywright>=1.42.0\naiosqlite>=0.20.0\npython-dotenv>=1.0.1\n', '.env.example': 'BOT_TOKEN=1234567890:AAH_YOUR_TELEGRAM_BOT_TOKEN_HERE\nADMIN_ID=123456789\nHEADLESS=false\nMIN_INTERVAL=45\nMAX_INTERVAL=90\n', 'config.py': 'import os\nfrom pathlib import Path\nfrom dotenv import load_dotenv\n\nload_dotenv()\n\nBASE_DIR = Path(__file__).resolve().parent\nSESSION_DIR = BASE_DIR / "uzum_session"\nSCREENSHOTS_DIR = BASE_DIR / "screenshots"\nDB_PATH = BASE_DIR / "uzum_sniper.db"\n\nSESSION_DIR.mkdir(parents=True, exist_ok=True)\nSCREENSHOTS_DIR.mkdir(parents=True, exist_ok=True)\n\nBOT_TOKEN = os.getenv("BOT_TOKEN", "YOUR_BOT_TOKEN_HERE")\nADMIN_ID = int(os.getenv("ADMIN_ID", "0"))\n\n# Birinchi marta login qilishda HEADLESS=false bo\'ladi, serverda HEADLESS=true qilinadi\nHEADLESS = os.getenv("HEADLESS", "false").lower() in ("true", "1", "yes")\n\n# Anti-Ban kutish oralig\'i (45 - 90 soniya)\nMIN_CHECK_INTERVAL = int(os.getenv("MIN_INTERVAL", "45"))\nMAX_CHECK_INTERVAL = int(os.getenv("MAX_INTERVAL", "90"))\n', 'database.py': 'import aiosqlite\nfrom config import DB_PATH\n\n\nasync def init_db():\n    async with aiosqlite.connect(DB_PATH) as db:\n        await db.execute(\'\'\'\n            CREATE TABLE IF NOT EXISTS products (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                user_id INTEGER NOT NULL,\n                url TEXT NOT NULL,\n                title TEXT DEFAULT \'Uzum Mahsuloti\',\n                target_price INTEGER NOT NULL,\n                last_price INTEGER DEFAULT NULL,\n                available_amount INTEGER DEFAULT 0,\n                mode TEXT NOT NULL DEFAULT \'MODE_A\',\n                status TEXT NOT NULL DEFAULT \'ACTIVE\',\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                completed_at TIMESTAMP DEFAULT NULL\n            )\n        \'\'\')\n        await db.commit()\n\n\nasync def add_product(user_id: int, url: str, target_price: int, mode: str) -> int:\n    async with aiosqlite.connect(DB_PATH) as db:\n        cursor = await db.execute(\n            \'\'\'\n            INSERT INTO products (user_id, url, target_price, mode, status)\n            VALUES (?, ?, ?, ?, \'ACTIVE\')\n            \'\'\',\n            (user_id, url, target_price, mode)\n        )\n        await db.commit()\n        return cursor.lastrowid\n\n\nasync def get_active_products() -> list[dict]:\n    async with aiosqlite.connect(DB_PATH) as db:\n        db.row_factory = aiosqlite.Row\n        cursor = await db.execute(\n            "SELECT * FROM products WHERE status = \'ACTIVE\' ORDER BY id ASC"\n        )\n        rows = await cursor.fetchall()\n        return [dict(r) for r in rows]\n\n\nasync def get_user_products(user_id: int) -> list[dict]:\n    async with aiosqlite.connect(DB_PATH) as db:\n        db.row_factory = aiosqlite.Row\n        cursor = await db.execute(\n            "SELECT * FROM products WHERE user_id = ? ORDER BY id DESC LIMIT 20",\n            (user_id,)\n        )\n        rows = await cursor.fetchall()\n        return [dict(r) for r in rows]\n\n\nasync def get_product_by_id(product_id: int) -> dict | None:\n    async with aiosqlite.connect(DB_PATH) as db:\n        db.row_factory = aiosqlite.Row\n        cursor = await db.execute(\n            "SELECT * FROM products WHERE id = ?",\n            (product_id,)\n        )\n        row = await cursor.fetchone()\n        return dict(row) if row else None\n\n\nasync def update_product_metrics(product_id: int, title: str, last_price: int, available_amount: int):\n    async with aiosqlite.connect(DB_PATH) as db:\n        await db.execute(\n            \'\'\'\n            UPDATE products\n            SET title = ?, last_price = ?, available_amount = ?\n            WHERE id = ?\n            \'\'\',\n            (title, last_price, available_amount, product_id)\n        )\n        await db.commit()\n\n\nasync def acquire_safety_lock(product_id: int) -> bool:\n    \'\'\'\n    Safety Lock: Bitta tovarni 2 marta sotib olmaslik uchun atomar blokirovka.\n    Faqat ACTIVE yoki NOTIFIED holatdagi tovarni PROCESSING holatiga o\'tkazadi.\n    \'\'\'\n    async with aiosqlite.connect(DB_PATH) as db:\n        cursor = await db.execute(\n            \'\'\'\n            UPDATE products\n            SET status = \'PROCESSING\'\n            WHERE id = ? AND status IN (\'ACTIVE\', \'NOTIFIED\')\n            \'\'\',\n            (product_id,)\n        )\n        await db.commit()\n        return cursor.rowcount > 0\n\n\nasync def mark_status(product_id: int, status: str):\n    async with aiosqlite.connect(DB_PATH) as db:\n        if status == \'COMPLETED\':\n            await db.execute(\n                \'\'\'\n                UPDATE products\n                SET status = \'COMPLETED\', completed_at = CURRENT_TIMESTAMP\n                WHERE id = ?\n                \'\'\',\n                (product_id,)\n            )\n        else:\n            await db.execute(\n                "UPDATE products SET status = ? WHERE id = ?",\n                (status, product_id)\n            )\n        await db.commit()\n\n\nasync def delete_product(product_id: int, user_id: int) -> bool:\n    async with aiosqlite.connect(DB_PATH) as db:\n        cursor = await db.execute(\n            "DELETE FROM products WHERE id = ? AND user_id = ?",\n            (product_id, user_id)\n        )\n        await db.commit()\n        return cursor.rowcount > 0\n', 'browser_manager.py': 'import asyncio\nimport json\nimport re\nimport time\nfrom pathlib import Path\nfrom playwright.async_api import async_playwright, BrowserContext, Page, Response\nfrom config import SESSION_DIR, SCREENSHOTS_DIR, HEADLESS\n\n\nclass UzumBrowserManager:\n    def __init__(self):\n        self.playwright = None\n        self.context: BrowserContext | None = None\n        self._lock = asyncio.Lock()\n\n    async def start(self, headless: bool = HEADLESS):\n        if self.context is not None:\n            return\n        self.playwright = await async_playwright().start()\n        self.context = await self.playwright.chromium.launch_persistent_context(\n            user_data_dir=str(SESSION_DIR),\n            headless=headless,\n            viewport={"width": 1366, "height": 820},\n            locale="uz-UZ",\n            args=[\n                "--disable-blink-features=AutomationControlled",\n                "--no-sandbox",\n                "--disable-dev-shm-usage",\n            ],\n        )\n\n    async def stop(self):\n        if self.context:\n            await self.context.close()\n            self.context = None\n        if self.playwright:\n            await self.playwright.stop()\n            self.playwright = None\n\n    def _extract_sku_from_json(self, data: dict, target_sku_id: str | None = None) -> dict | None:\n        \'\'\'\n        Uzum API v2 yoki GraphQL JSON javobidan title, purchasePrice va availableAmount ni ajratib oladi.\n        \'\'\'\n        payload = data.get("payload", {})\n        product_obj = payload.get("data", data.get("data", data))\n        if not isinstance(product_obj, dict):\n            return None\n\n        sku_list = product_obj.get("skuList")\n        if not isinstance(sku_list, list) or not sku_list:\n            return None\n\n        title = product_obj.get("title", "Uzum Mahsuloti")\n        chosen_sku = None\n\n        if target_sku_id:\n            for sku in sku_list:\n                if str(sku.get("id")) == str(target_sku_id):\n                    chosen_sku = sku\n                    break\n\n        if not chosen_sku:\n            # Omborda qoldig\'i bor eng arzon SKU ni tanlash\n            in_stock_skus = [s for s in sku_list if int(s.get("availableAmount", 0)) > 0]\n            if in_stock_skus:\n                chosen_sku = min(\n                    in_stock_skus,\n                    key=lambda s: int(s.get("purchasePrice") or s.get("fullPrice") or 999999999)\n                )\n            else:\n                chosen_sku = sku_list[0]\n\n        price = int(chosen_sku.get("purchasePrice") or chosen_sku.get("fullPrice") or 0)\n        available = int(chosen_sku.get("availableAmount") or 0)\n\n        if price <= 0:\n            return None\n\n        return {\n            "title": title,\n            "price": price,\n            "available_amount": available,\n            "sku_id": chosen_sku.get("id"),\n        }\n\n    async def check_price_and_stock(self, product_url: str) -> dict | None:\n        \'\'\'\n        Sahifani ochib page.on("response") orqali Uzum ichki JSON API javobidan\n        aniq narx va ombordagi qoldiqni (availableAmount) o\'qiydi.\n        \'\'\'\n        async with self._lock:\n            await self.start(headless=HEADLESS)\n            page = await self.context.new_page()\n            captured_result = None\n\n            # URL ichida ?skuId= bo\'lsa ajratib olamiz\n            sku_match = re.search(r"skuId=(\\d+)", product_url)\n            target_sku_id = sku_match.group(1) if sku_match else None\n\n            async def on_response(response: Response):\n                nonlocal captured_result\n                if captured_result is not None:\n                    return\n                ctype = response.headers.get("content-type", "")\n                if "application/json" not in ctype:\n                    return\n                url = response.url\n                if any(k in url for k in ["api.uzum.uz", "/product/", "graphql", "v2/product"]):\n                    try:\n                        raw = await response.json()\n                        parsed = self._extract_sku_from_json(raw, target_sku_id)\n                        if parsed:\n                            captured_result = parsed\n                    except Exception:\n                        pass\n\n            page.on("response", on_response)\n\n            try:\n                await page.goto(product_url, wait_until="domcontentloaded", timeout=45000)\n                # JSON API javobi kelishini maksimal 8 soniya kutamiz\n                for _ in range(16):\n                    if captured_result is not None:\n                        break\n                    await asyncio.sleep(0.5)\n\n                # Fallback: Agar kesh tufayli XHR tutib bo\'lmasa, DOM/window state dan o\'qiymiz\n                if captured_result is None:\n                    captured_result = await self._fallback_dom_extract(page)\n\n                return captured_result\n            except Exception as e:\n                print(f"[check_price_and_stock] Xatolik: {e}")\n                return None\n            finally:\n                await page.close()\n\n    async def _fallback_dom_extract(self, page: Page) -> dict | None:\n        try:\n            title_el = page.locator("h1").first\n            title = (await title_el.inner_text()).strip() if await title_el.count() > 0 else "Uzum Mahsuloti"\n\n            price_selectors = [\n                "[data-test-id=\'text__product-price\']",\n                ".currency",\n                "[class*=\'price\']",\n            ]\n            price_val = 0\n            for sel in price_selectors:\n                loc = page.locator(sel).first\n                if await loc.count() > 0:\n                    txt = await loc.inner_text()\n                    digits = re.sub(r"[^\\d]", "", txt)\n                    if digits:\n                        price_val = int(digits)\n                        break\n\n            # Savatga qo\'shish tugmasi faol bo\'lsa qoldiq > 0 deb olamiz\n            add_btn = page.locator(\n                "button[data-test-id=\'button__add-cart\'], "\n                "button:has-text(\'Savatga\'), "\n                "button:has-text(\'В корзину\')"\n            ).first\n            available = 1 if await add_btn.count() > 0 and await add_btn.is_enabled() else 0\n\n            if price_val > 0:\n                return {\n                    "title": title,\n                    "price": price_val,\n                    "available_amount": available,\n                    "sku_id": None,\n                }\n        except Exception:\n            pass\n        return None\n\n    async def auto_checkout(self, product_url: str, product_id: int) -> dict:\n        \'\'\'\n        Mode A va Mode B uchun Auto-Checkout:\n        1. Mahsulot sahifasini ochadi va savatga qo\'shadi.\n        2. Savat va Rasmiylashtirish (Checkout) sahifasiga o\'tadi.\n        3. PVZ (Topshirish punkti) va \'Topshirish punktida to\'lash\' (Оплата при получении) usulini tanlaydi.\n        4. Buyurtmani tasdiqlaydi va yakuniy skrinshotni saqlaydi.\n        \'\'\'\n        async with self._lock:\n            await self.start(headless=HEADLESS)\n            page = await self.context.new_page()\n            screenshot_path = SCREENSHOTS_DIR / f"order_{product_id}_{int(time.time())}.png"\n\n            try:\n                await page.goto(product_url, wait_until="networkidle", timeout=60000)\n                await asyncio.sleep(1.5)\n\n                # 1. Savatga qo\'shish tugmasini bosish\n                add_to_cart_selectors = [\n                    "button[data-test-id=\'button__add-cart\']",\n                    "button[data-test-id=\'button__add-to-cart\']",\n                    "button:has-text(\'Savatga qoʻshish\')",\n                    "button:has-text(\'Savatga\')",\n                    "button:has-text(\'В корзину\')",\n                ]\n                added = False\n                for sel in add_to_cart_selectors:\n                    loc = page.locator(sel).first\n                    if await loc.count() > 0 and await loc.is_visible():\n                        await loc.click()\n                        added = True\n                        break\n\n                if not added:\n                    # Agar allaqachon savatda bo\'lsa ("Savatda" / "O\'tish" tugmasi chiqib tursa)\n                    in_cart_loc = page.locator("a[href*=\'/cart\'], button:has-text(\'Savatga oʻtish\'), button:has-text(\'Перейти в корзину\')").first\n                    if await in_cart_loc.count() == 0:\n                        await page.screenshot(path=str(screenshot_path), full_page=True)\n                        return {\n                            "success": False,\n                            "error": "Savatga qo\'shish tugmasi topilmadi yoki tovar tugagan.",\n                            "screenshot": str(screenshot_path),\n                        }\n\n                await asyncio.sleep(1.5)\n\n                # 2. Savatga o\'tish va Rasmiylashtirish (Checkout) bosqichi\n                await page.goto("https://uzum.uz/uz/cart", wait_until="networkidle", timeout=45000)\n                await asyncio.sleep(2.0)\n\n                checkout_btn_selectors = [\n                    "button[data-test-id=\'button__checkout\']",\n                    "button[data-test-id=\'cart__checkout-btn\']",\n                    "button:has-text(\'Rasmiylashtirishga oʻtish\')",\n                    "button:has-text(\'Rasmiylashtirish\')",\n                    "button:has-text(\'Перейти к оформлению\')",\n                    "button:has-text(\'К оформлению\')",\n                ]\n                for sel in checkout_btn_selectors:\n                    btn = page.locator(sel).first\n                    if await btn.count() > 0 and await btn.is_visible():\n                        await btn.click()\n                        break\n\n                await asyncio.sleep(3.0)\n\n                # 3. "Topshirish punktida to\'lash" (Оплата при получении) usulini tanlash\n                pay_on_delivery_selectors = [\n                    "[data-test-id*=\'payment-upon-receipt\']",\n                    "[data-test-id*=\'cash\']",\n                    "label:has-text(\'Topshirish punktida\')",\n                    "div:has-text(\'Topshirish punktida toʻlash\')",\n                    "span:has-text(\'Topshirish punktida\')",\n                    "label:has-text(\'При получении\')",\n                    "span:has-text(\'Оплата при получении\')",\n                ]\n                for sel in pay_on_delivery_selectors:\n                    pay_el = page.locator(sel).first\n                    if await pay_el.count() > 0 and await pay_el.is_visible():\n                        try:\n                            await pay_el.click()\n                            await asyncio.sleep(1.0)\n                            break\n                        except Exception:\n                            continue\n\n                # 4. Yakuniy "Buyurtma berish" / "To\'lov qilish" tugmasini bosish\n                place_order_selectors = [\n                    "button[data-test-id=\'button__make-order\']",\n                    "button[data-test-id=\'checkout__submit\']",\n                    "button:has-text(\'Buyurtmani rasmiylashtirish\')",\n                    "button:has-text(\'Buyurtma berish\')",\n                    "button:has-text(\'Оформить заказ\')",\n                    "button:has-text(\'Заказать\')",\n                ]\n                order_clicked = False\n                for sel in place_order_selectors:\n                    order_btn = page.locator(sel).first\n                    if await order_btn.count() > 0 and await order_btn.is_visible() and await order_btn.is_enabled():\n                        await order_btn.click()\n                        order_clicked = True\n                        break\n\n                await asyncio.sleep(4.0)\n                await page.screenshot(path=str(screenshot_path), full_page=True)\n\n                if not order_clicked:\n                    return {\n                        "success": False,\n                        "error": "Checkout sahifasida yakuniy tasdiqlash tugmasi bosilmadi (PVZ yoki Login holatini skrinshotdan tekshiring).",\n                        "screenshot": str(screenshot_path),\n                    }\n\n                return {\n                    "success": True,\n                    "error": None,\n                    "screenshot": str(screenshot_path),\n                }\n\n            except Exception as e:\n                try:\n                    await page.screenshot(path=str(screenshot_path), full_page=True)\n                except Exception:\n                    pass\n                return {\n                    "success": False,\n                    "error": str(e),\n                    "screenshot": str(screenshot_path) if screenshot_path.exists() else None,\n                }\n            finally:\n                await page.close()\n\n\nasync def interactive_login():\n    \'\'\'\n    Birinchi marta ishga tushirganda (python browser_manager.py --login)\n    foydalanuvchi Uzum profiliga kirishi va PVZ tanlashi uchun oyna ochadi.\n    \'\'\'\n    print("=" * 65)\n    print("[UZUM SESSION SETUP] Brauzer ochilmoqda (headless=False)...")\n    print("1. Telefon raqamingiz va SMS kod orqali Uzum profilingizga kiring.")\n    print("2. Asosiy manzil sifatida o\'zingizga yaqin Topshirish punktini (PVZ) tanlang.")\n    print("3. Tayyor bo\'lgach, shu terminalda ENTER tugmasini bosing.")\n    print("=" * 65)\n\n    manager = UzumBrowserManager()\n    await manager.start(headless=False)\n    page = await manager.context.new_page()\n    await page.goto("https://uzum.uz", wait_until="domcontentloaded")\n\n    await asyncio.to_thread(input, "\\n>>> Login va PVZ tanlab bo\'lgach ENTER bosing... ")\n    await manager.stop()\n    print("[+] Sessiya \'./uzum_session\' papkasiga muvaffaqiyatli saqlandi!")\n\n\nif __name__ == "__main__":\n    asyncio.run(interactive_login())\n', 'monitor.py': 'import asyncio\nimport random\nfrom aiogram import Bot\nfrom aiogram.types import InlineKeyboardMarkup, InlineKeyboardButton, FSInputFile\nfrom config import MIN_CHECK_INTERVAL, MAX_CHECK_INTERVAL\nfrom database import (\n    get_active_products,\n    update_product_metrics,\n    acquire_safety_lock,\n    mark_status,\n)\nfrom browser_manager import UzumBrowserManager\n\n\nclass PriceMonitor:\n    def __init__(self, bot: Bot, browser_manager: UzumBrowserManager):\n        self.bot = bot\n        self.browser = browser_manager\n        self.running = False\n\n    async def start_loop(self):\n        self.running = True\n        print("[Monitor] Narx kuzatuvchisi ishga tushdi (Anti-Ban: 45-90s)...")\n\n        while self.running:\n            products = await get_active_products()\n            if not products:\n                await asyncio.sleep(15)\n                continue\n\n            for item in products:\n                if not self.running:\n                    break\n\n                product_id = item["id"]\n                user_id = item["user_id"]\n                url = item["url"]\n                target_price = item["target_price"]\n                mode = item["mode"]\n\n                info = await self.browser.check_price_and_stock(url)\n                if info:\n                    title = info["title"]\n                    current_price = info["price"]\n                    available = info["available_amount"]\n\n                    await update_product_metrics(product_id, title, current_price, available)\n                    print(\n                        f"[Monitor] ID #{product_id} | {title[:30]} | "\n                        f"Narx: {current_price:,} so\'m (Maqsad: {target_price:,}) | Qoldiq: {available}"\n                    )\n\n                    # Narx maqsadli narxga tushgan va omborda mavjud bo\'lsa\n                    if current_price <= target_price and available > 0:\n                        if mode == "MODE_A":\n                            # Mode A: Auto-Buy Sniper (Darhol xarid qilish va Safety Lock)\n                            locked = await acquire_safety_lock(product_id)\n                            if locked:\n                                await self.bot.send_message(\n                                    user_id,\n                                    f"🎯 <b>SNIPER TRIGGER (Mode A)!</b>\\n\\n"\n                                    f"📦 <b>{title}</b>\\n"\n                                    f"💰 Joriy narx: <b>{current_price:,} so\'m</b> (Maqsad: {target_price:,} so\'m)\\n"\n                                    f"📦 Omborda: <b>{available} ta</b>\\n\\n"\n                                    f"⚡ Avtomatik xarid boshlandi...",\n                                    parse_mode="HTML",\n                                )\n                                result = await self.browser.auto_checkout(url, product_id)\n                                if result["success"]:\n                                    await mark_status(product_id, "COMPLETED")\n                                    caption = (\n                                        f"✅ <b>XARID MUVAFFAQIYATLI YAKUNLANDI!</b>\\n\\n"\n                                        f"📦 Tovar: <b>{title}</b>\\n"\n                                        f"💵 Xarid narxi: <b>{current_price:,} so\'m</b>\\n"\n                                        f"🔒 Status: <b>COMPLETED</b> (Safety Lock faollashdi, kuzatuv to\'xtatildi)"\n                                    )\n                                else:\n                                    await mark_status(product_id, "FAILED")\n                                    caption = (\n                                        f"⚠️ <b>Avto-xaridda xatolik yuz berdi!</b>\\n\\n"\n                                        f"📦 Tovar: <b>{title}</b>\\n"\n                                        f"❌ Sabab: {result[\'error\']}\\n"\n                                        f"🔒 Qayta xarid bo\'lmasligi uchun kuzatuv to\'xtatildi."\n                                    )\n\n                                if result.get("screenshot"):\n                                    photo = FSInputFile(result["screenshot"])\n                                    await self.bot.send_photo(user_id, photo=photo, caption=caption, parse_mode="HTML")\n                                else:\n                                    await self.bot.send_message(user_id, caption, parse_mode="HTML")\n\n                        elif mode == "MODE_B":\n                            # Mode B: 1-Click Confirm (Xabar va [Sotib olish] inline tugmasi)\n                            await mark_status(product_id, "NOTIFIED")\n                            kb = InlineKeyboardMarkup(\n                                inline_keyboard=[\n                                    [\n                                        InlineKeyboardButton(\n                                            text="🛒 Sotib olish (1-Click PVZ)",\n                                            callback_data=f"buy_now:{product_id}",\n                                        )\n                                    ],\n                                    [\n                                        InlineKeyboardButton(\n                                            text="❌ Bekor qilish",\n                                            callback_data=f"delete:{product_id}",\n                                        )\n                                    ],\n                                ]\n                            )\n                            await self.bot.send_message(\n                                user_id,\n                                f"🔔 <b>NARX TUSHDI (Mode B)!</b>\\n\\n"\n                                f"📦 <b>{title}</b>\\n"\n                                f"💰 Yangi narx: <b>{current_price:,} so\'m</b> (Maqsad: {target_price:,} so\'m)\\n"\n                                f"📦 Omborda qoldiq: <b>{available} ta</b>\\n\\n"\n                                f"Darhol PVZga buyurtma berish uchun quyidagi tugmani bosing:",\n                                reply_markup=kb,\n                                parse_mode="HTML",\n                            )\n\n                # Anti-Ban: Har bir tovar orasida 45-90 soniya random kechikish\n                delay = random.randint(MIN_CHECK_INTERVAL, MAX_CHECK_INTERVAL)\n                print(f"[Anti-Ban] Keyingi tekshiruvgacha {delay} soniya kutilmoqda...")\n                await asyncio.sleep(delay)\n', 'bot.py': 'import asyncio\nimport re\nfrom aiogram import Bot, Dispatcher, F\nfrom aiogram.filters import CommandStart, Command\nfrom aiogram.types import (\n    Message,\n    CallbackQuery,\n    InlineKeyboardMarkup,\n    InlineKeyboardButton,\n    FSInputFile,\n)\nfrom aiogram.fsm.context import FSMContext\nfrom aiogram.fsm.state import State, StatesGroup\n\nfrom config import BOT_TOKEN, ADMIN_ID\nfrom database import (\n    init_db,\n    add_product,\n    get_user_products,\n    get_product_by_id,\n    acquire_safety_lock,\n    mark_status,\n    delete_product,\n)\nfrom browser_manager import UzumBrowserManager\nfrom monitor import PriceMonitor\n\n\nclass AddProductFSM(StatesGroup):\n    waiting_for_price = State()\n    waiting_for_mode = State()\n\n\nbot = Bot(token=BOT_TOKEN)\ndp = Dispatcher()\nbrowser_manager = UzumBrowserManager()\nmonitor = PriceMonitor(bot, browser_manager)\n\n\ndef is_authorized(user_id: int) -> bool:\n    if ADMIN_ID == 0:\n        return True\n    return user_id == ADMIN_ID\n\n\n@dp.message(CommandStart())\nasync def cmd_start(message: Message, state: FSMContext):\n    if not is_authorized(message.from_user.id):\n        await message.answer("⛔ Sizda ushbu shaxsiy botdan foydalanish huquqi yo\'q.")\n        return\n\n    await state.clear()\n    await message.answer(\n        "🚀 <b>Uzum Market Price Tracker & Auto-Buy Sniper</b> botiga xush kelibsiz!\\n\\n"\n        "📌 <b>Qo\'llanma:</b>\\n"\n        "1. Menga Uzum mahsuloti havolasini (<code>https://uzum.uz/...</code>) yuboring.\\n"\n        "2. Kutilayotgan maqsadli narxni (<code>target_price</code>) kiriting.\\n"\n        "3. Rejimni tanlang:\\n"\n        "   • <b>Mode A (Auto-Buy Sniper)</b> — Narx tushishi bilan avtomatik PVZga xarid qiladi.\\n"\n        "   • <b>Mode B (1-Click Confirm)</b> — Narx tushganda xabar va <b>[Sotib olish]</b> tugmasini yuboradi.\\n\\n"\n        "📋 <b>Buyruqlar:</b>\\n"\n        "/list — Kuzatilayotgan tovarlar ro\'yxati\\n"\n        "/login — Serverda brauzer sessiyasi holatini tekshirish",\n        parse_mode="HTML",\n    )\n\n\n@dp.message(Command("list"))\nasync def cmd_list(message: Message):\n    if not is_authorized(message.from_user.id):\n        return\n\n    items = await get_user_products(message.from_user.id)\n    if not items:\n        await message.answer("📭 Hozircha kuzatilayotgan tovarlar yo\'q. Uzum havolasini yuboring!")\n        return\n\n    for item in items:\n        last_p = f"{item[\'last_price\']:,} so\'m" if item["last_price"] else "Hali tekshirilmadi"\n        mode_label = "⚡ Mode A (Auto-Buy)" if item["mode"] == "MODE_A" else "🔔 Mode B (1-Click)"\n        kb = InlineKeyboardMarkup(\n            inline_keyboard=[\n                [\n                    InlineKeyboardButton(\n                        text="🛒 Hozir sotib olish",\n                        callback_data=f"buy_now:{item[\'id\']}",\n                    ),\n                    InlineKeyboardButton(\n                        text="🗑 O\'chirish",\n                        callback_data=f"delete:{item[\'id\']}",\n                    ),\n                ]\n            ]\n        )\n        await message.answer(\n            f"🆔 <b>#{item[\'id\']} | {item[\'title\']}</b>\\n"\n            f"🎯 Maqsadli narx: <b>{item[\'target_price\']:,} so\'m</b>\\n"\n            f"💰 Oxirgi narx: <b>{last_p}</b> (Qoldiq: {item[\'available_amount\']} ta)\\n"\n            f"⚙️ Rejim: <b>{mode_label}</b>\\n"\n            f"📌 Status: <b>{item[\'status\']}</b>\\n"\n            f"🔗 <a href=\'{item[\'url\']}\'>Mahsulot havolasi</a>",\n            reply_markup=kb,\n            parse_mode="HTML",\n            disable_web_page_preview=True,\n        )\n\n\n@dp.message(F.text.contains("uzum.uz"))\nasync def handle_uzum_link(message: Message, state: FSMContext):\n    if not is_authorized(message.from_user.id):\n        return\n\n    url_match = re.search(r"(https?://[^\\s]+uzum\\.uz[^\\s]*)", message.text)\n    if not url_match:\n        await message.answer("⚠️ To\'g\'ri Uzum.uz mahsulot havolasini yuboring.")\n        return\n\n    clean_url = url_match.group(1)\n    await state.update_data(url=clean_url)\n    await state.set_state(AddProductFSM.waiting_for_price)\n    await message.answer(\n        "💰 <b>Maqsadli narxni (target_price) kiriting (so\'mda):</b>\\n"\n        "Masalan: <code>150000</code>",\n        parse_mode="HTML",\n    )\n\n\n@dp.message(AddProductFSM.waiting_for_price)\nasync def handle_target_price(message: Message, state: FSMContext):\n    digits = re.sub(r"[^\\d]", "", message.text or "")\n    if not digits or int(digits) <= 0:\n        await message.answer("⚠️ Iltimos, narxni faqat raqamlarda kiriting (masalan: <code>125000</code>):", parse_mode="HTML")\n        return\n\n    target_price = int(digits)\n    await state.update_data(target_price=target_price)\n    await state.set_state(AddProductFSM.waiting_for_mode)\n\n    kb = InlineKeyboardMarkup(\n        inline_keyboard=[\n            [\n                InlineKeyboardButton(\n                    text="⚡ Mode A: Auto-Buy Sniper (Avto-Xarid)",\n                    callback_data="select_mode:MODE_A",\n                )\n            ],\n            [\n                InlineKeyboardButton(\n                    text="🔔 Mode B: 1-Click Confirm (Tasdiqlash bilan)",\n                    callback_data="select_mode:MODE_B",\n                )\n            ],\n        ]\n    )\n    await message.answer(\n        f"🎯 Maqsadli narx: <b>{target_price:,} so\'m</b>\\n\\n"\n        f"Endi xarid rejimini tanlang:",\n        reply_markup=kb,\n        parse_mode="HTML",\n    )\n\n\n@dp.callback_query(AddProductFSM.waiting_for_mode, F.data.startswith("select_mode:"))\nasync def handle_mode_selection(call: CallbackQuery, state: FSMContext):\n    mode = call.data.split(":")[1]\n    data = await state.get_data()\n    url = data["url"]\n    target_price = data["target_price"]\n\n    product_id = await add_product(\n        user_id=call.from_user.id,\n        url=url,\n        target_price=target_price,\n        mode=mode,\n    )\n    await state.clear()\n\n    mode_desc = (\n        "⚡ <b>Mode A (Auto-Buy Sniper)</b> — Narx tushishi bilan avtomatik PVZga buyurtma beriladi."\n        if mode == "MODE_A"\n        else "🔔 <b>Mode B (1-Click Confirm)</b> — Narx tushishi bilan sizga [Sotib olish] tugmasi yuboriladi."\n    )\n\n    await call.message.edit_text(\n        f"✅ <b>Tovar kuzatuvga qo\'shildi! (ID: #{product_id})</b>\\n\\n"\n        f"🔗 Havola: {url}\\n"\n        f"🎯 Maqsadli narx: <b>{target_price:,} so\'m</b>\\n"\n        f"⚙️ Rejim: {mode_desc}\\n"\n        f"⏱ Tekshirish intervali: <b>45–90 soniya (Anti-Ban)</b>",\n        parse_mode="HTML",\n        disable_web_page_preview=True,\n    )\n    await call.answer()\n\n\n@dp.callback_query(F.data.startswith("buy_now:"))\nasync def handle_one_click_buy(call: CallbackQuery):\n    product_id = int(call.data.split(":")[1])\n    product = await get_product_by_id(product_id)\n\n    if not product:\n        await call.answer("Tovar topilmadi!", show_alert=True)\n        return\n\n    if product["status"] == "COMPLETED":\n        await call.answer("🔒 Bu tovar allaqachon xarid qilingan (Safety Lock)!", show_alert=True)\n        return\n\n    locked = await acquire_safety_lock(product_id)\n    if not locked:\n        await call.answer("⏳ Xarid jarayoni allaqachon ketmoqda yoki yakunlangan!", show_alert=True)\n        return\n\n    await call.answer("⚡ Auto-Checkout boshlandi!")\n    await call.message.edit_text(\n        f"⚡ <b>1-Click Auto-Checkout bajarilmoqda...</b>\\n"\n        f"📦 Tovar: <b>{product[\'title\']}</b>\\n"\n        f"Iltimos, 10-15 soniya kuting, yakuniy skrinshot yuboriladi.",\n        parse_mode="HTML",\n    )\n\n    result = await browser_manager.auto_checkout(product["url"], product_id)\n    if result["success"]:\n        await mark_status(product_id, "COMPLETED")\n        caption = (\n            f"✅ <b>1-CLICK XARID MUVAFFAQIYATLI YAKUNLANDI!</b>\\n\\n"\n            f"📦 Tovar: <b>{product[\'title\']}</b>\\n"\n            f"🔒 Status: <b>COMPLETED</b> (Safety Lock faollashdi)"\n        )\n    else:\n        await mark_status(product_id, "FAILED")\n        caption = (\n            f"⚠️ <b>Xaridda xatolik:</b> {result[\'error\']}\\n"\n            f"Skrinshotni tekshiring."\n        )\n\n    if result.get("screenshot"):\n        photo = FSInputFile(result["screenshot"])\n        await call.message.answer_photo(photo=photo, caption=caption, parse_mode="HTML")\n    else:\n        await call.message.answer(caption, parse_mode="HTML")\n\n\n@dp.callback_query(F.data.startswith("delete:"))\nasync def handle_delete_product(call: CallbackQuery):\n    product_id = int(call.data.split(":")[1])\n    deleted = await delete_product(product_id, call.from_user.id)\n    if deleted:\n        await call.message.edit_text(f"🗑 Tovar #{product_id} kuzatuvdan o\'chirildi.")\n    else:\n        await call.answer("Tovar topilmadi.", show_alert=True)\n\n\nasync def main():\n    await init_db()\n    asyncio.create_task(monitor.start_loop())\n    print("[Bot] Telegram bot ishga tushdi...")\n    try:\n        await dp.start_polling(bot)\n    finally:\n        await browser_manager.stop()\n\n\nif __name__ == "__main__":\n    asyncio.run(main())\n', 'Dockerfile': 'FROM mcr.microsoft.com/playwright/python:v1.42.0-jammy\n\nWORKDIR /app\n\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nRUN playwright install chromium\n\nCOPY . .\n\nCMD ["python", "bot.py"]\n'}

def install():
    base = Path(".")
    (base / "uzum_session").mkdir(exist_ok=True)
    (base / "screenshots").mkdir(exist_ok=True)
    for name, content in FILES.items():
        Path(name).write_text(content, encoding="utf-8")
        print(f"[+] Yaratildi: {name} ({len(content.splitlines())} qator)")
    print("[SUCCESS] Barcha fayllar to'liq va qisqartirishlarsiz yaratildi!")

if __name__ == "__main__":
    install()
